from typing import List, Optional
from fastapi import APIRouter, Depends, HTTPException, status, Query
from sqlalchemy.orm import Session
import json # Import json module

from app.database import get_db
from app.models.recipe import Recipe
from app.models.user import User
from app.schemas.recipe import RecipeCreate, RecipeUpdate, RecipeResponse
from app.utils.auth import get_current_user

recipe_router = APIRouter()


@recipe_router.get("/recipes", response_model=List[RecipeResponse])
def get_recipes(
    search: Optional[str] = Query(None),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db)
):
    query = db.query(Recipe)
    if search:
        query = query.filter(Recipe.title.ilike(f\"%{search}%\"))
    recipes = query.order_by(Recipe.created_at.desc()).offset(offset).limit(limit).all()
    # Deserialize JSON strings back to lists for the response model
    for recipe in recipes:
        if isinstance(recipe.ingredients, str):
            recipe.ingredients = json.loads(recipe.ingredients)
        if isinstance(recipe.instructions, str):
            recipe.instructions = json.loads(recipe.instructions)
    return recipes


@recipe_router.get("/recipes/{recipe_id}", response_model=RecipeResponse)
def get_recipe(recipe_id: int, db: Session = Depends(get_db)):
    recipe = db.query(Recipe).filter(Recipe.id == recipe_id).first()
    if not recipe:
        raise HTTPException(status_code=404, detail=\"Recipe not found\")
    # Deserialize JSON strings back to lists for the response model
    if isinstance(recipe.ingredients, str):
        recipe.ingredients = json.loads(recipe.ingredients)
    if isinstance(recipe.instructions, str):
        recipe.instructions = json.loads(recipe.instructions)
    return recipe


@recipe_router.post("/recipes", response_model=RecipeResponse, status_code=status.HTTP_201_CREATED)
def create_recipe(
    recipe_in: RecipeCreate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    # Convert lists to JSON strings for SQLite storage
    recipe_data = recipe_in.dict()
    if 'ingredients' in recipe_data and isinstance(recipe_data['ingredients'], list):
        recipe_data['ingredients'] = json.dumps(recipe_data['ingredients'])
    if 'instructions' in recipe_data and isinstance(recipe_data['instructions'], list):
        recipe_data['instructions'] = json.dumps(recipe_data['instructions'])

    # Create a dictionary for Recipe model instantiation, including all relevant fields
    # and explicitly setting user_id
    recipe_for_db = {k: v for k, v in recipe_data.items() if k in Recipe.__table__.columns.keys()}
    recipe_for_db['user_id'] = current_user.id

    new_recipe = Recipe(**recipe_for_db)
    db.add(new_recipe)
    db.commit()
    db.refresh(new_recipe)
    # Deserialize JSON strings back to lists for the response model
    if isinstance(new_recipe.ingredients, str):
        new_recipe.ingredients = json.loads(new_recipe.ingredients)
    if isinstance(new_recipe.instructions, str):
        new_recipe.instructions = json.loads(new_recipe.instructions)
    return new_recipe


@recipe_router.put("/recipes/{recipe_id}", response_model=RecipeResponse)
def update_recipe(
    recipe_id: int,
    recipe_in: RecipeUpdate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    recipe = db.query(Recipe).filter(Recipe.id == recipe_id, Recipe.user_id == current_user.id).first()
    if not recipe:
        raise HTTPException(status_code=404, detail=\"Recipe not found or you don't have permission to edit it\")

    update_data = recipe_in.dict(exclude_unset=True)

    # Convert lists to JSON strings for SQLite storage if they are being updated
    if 'ingredients' in update_data and isinstance(update_data['ingredients'], list):
        update_data['ingredients'] = json.dumps(update_data['ingredients'])
    if 'instructions' in update_data and isinstance(update_data['instructions'], list):
        update_data['instructions'] = json.dumps(update_data['instructions'])

    for key, value in update_data.items():
        setattr(recipe, key, value)

    db.add(recipe)
    db.commit()
    db.refresh(recipe)
    # Deserialize JSON strings back to lists for the response model
    if isinstance(recipe.ingredients, str):
        recipe.ingredients = json.loads(recipe.ingredients)
    if isinstance(recipe.instructions, str):
        recipe.instructions = json.loads(recipe.instructions)
    return recipe


@recipe_router.delete("/recipes/{recipe_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_recipe(
    recipe_id: int,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    recipe = db.query(Recipe).filter(Recipe.id == recipe_id, Recipe.user_id == current_user.id).first()
    if not recipe:
        raise HTTPException(status_code=404, detail=\"Recipe not found or you don't have permission to delete it\")

    db.delete(recipe)
    db.commit()
    return {\"message\": \"Recipe deleted successfully\"}

