import React, { useState, useEffect } from 'react';
import API from '../api';

export default function DashboardPage() {
  const [stats, setStats] = useState({ total: 0, completed: 0, pending: 0 });
  const [tasks, setTasks] = useState([]);
  const [activity, setActivity] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchDashboardData() {
      try {
        const statsRes = await API.get('/stats');
        setStats(statsRes.data);

        const tasksRes = await API.get('/tasks');
        const items = tasksRes.data.items || [];
        setTasks(items);

        const days = [];
        const today = new Date();
        for (let i = 29; i >= 0; i--) {
          const d = new Date();
          d.setDate(today.getDate() - i);
          const dateStr = d.toISOString().split('T')[0];
          const hasCompleted = items.some(task => 
            task.done && task.updated_at && task.updated_at.startsWith(dateStr)
          );
          days.push({
            date: dateStr,
            active: hasCompleted
          });
        }
        setActivity(days);
      } catch (err) {
        console.error("Error fetching dashboard data", err);
      } finally {
        setLoading(false);
      }
    }
    fetchDashboardData();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-50 dark:bg-slate-900">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 p-6">
      <div className="max-w-7xl mx-auto space-y-8">
        <header className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Dashboard</h1>
            <p className="text-slate-500 dark:text-slate-400">Track your productivity and tasks</p>
          </div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
            <h3 className="text-sm font-medium text-slate-500 dark:text-slate-400">Total Tasks</h3>
            <p className="text-3xl font-bold text-slate-900 dark:text-white mt-2">{stats.total}</p>
          </div>
          <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
            <h3 className="text-sm font-medium text-slate-500 dark:text-slate-400">Completed</h3>
            <p className="text-3xl font-bold text-emerald-600 dark:text-emerald-400 mt-2">{stats.completed}</p>
          </div>
          <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
            <h3 className="text-sm font-medium text-slate-500 dark:text-slate-400">Pending</h3>
            <p className="text-3xl font-bold text-amber-500 dark:text-amber-400 mt-2">{stats.pending}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Activity (Last 30 Days)</h3>
          <div className="grid grid-cols-10 gap-2 max-w-lg">
            {activity.map((day, index) => (
              <div
                key={day.date}
                title={day.date}
                style={{ animationDelay: `${index * 15}ms` }}
                className={`animate-scale-in w-full aspect-square rounded-md transition-all duration-300 ${
                  day.active
                    ? 'bg-gradient-to-br from-indigo-500 to-violet-500 shadow-sm shadow-indigo-500/20'
                    : 'bg-slate-100 dark:bg-slate-700'
                }`}
              />
            ))}
