from app.models.user import User

try:
    from app.models.task import Task
except ImportError:
    from app.models.todo import Todo as Task

stat_router = APIRouter()

@stat_router.get("/stats")
def get_stats(
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    total = db.query(Task).filter(Task.user_id == current_user.id).count()
    completed = db.query(Task).filter(Task.user_id == current_user.id, Task.done == True).count()
    pending = total - completed

    return {
        "total": total,
        "completed": completed,
        "pending": pending
    }

