from datetime import datetime, date
from typing import Optional, List, Literal
from fastapi import APIRouter, Depends, HTTPException, Query, Path, status
from sqlalchemy.orm import Session
from sqlalchemy import or_

from app.database import get_db
from app.utils.auth import get_current_user
from app.models.contacts import Contact
from app.models.notes import Note
from app.models.interactions import Interaction
from app.schemas.contact import (
    NoteCreate,
    NoteResponse,
    InteractionCreate,
    InteractionResponse,
    ContactCreate,
    ContactUpdate,
    ContactResponse
)

contact_router = APIRouter()

# ------------------------------------------------------------------------
# ENDPOINTS
# ------------------------------------------------------------------------

@contact_router.get("/contacts", response_model=List[ContactResponse])
def get_contacts(
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    status_filter: Optional[str] = Query(None, alias="status"),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    query = db.query(Contact).filter(Contact.user_id == current_user.id)
    if status_filter:
        query = query.filter(Contact.status == status_filter)
    return query.offset(offset).limit(limit).all()

@contact_router.get("/contacts/search", response_model=List[ContactResponse])
def search_contacts(
    q: str = Query(..., min_length=1),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    query = db.query(Contact).filter(
        Contact.user_id == current_user.id,
        or_(
            Contact.name.ilike(f"%{q}%"),
            Contact.company.ilike(f"%{q}%")
        )
    )
    return query.offset(offset).limit(limit).all()

@contact_router.get("/contacts/{contact_id}", response_model=ContactResponse)
def get_contact(
    contact_id: int = Path(...),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    contact = db.query(Contact).filter(Contact.id == contact_id, Contact.user_id == current_user.id).first()
    if not contact:
        raise HTTPException(status_code=404, detail="Contact not found")
    return contact

@contact_router.post("/contacts", response_model=ContactResponse, status_code=status.HTTP_201_CREATED)
def create_contact(
    contact_in: ContactCreate,
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    contact = Contact(
        name=contact_in.name,
        email=contact_in.email,
        phone=contact_in.phone,
        company=contact_in.company,
        status=contact_in.status,
        user_id=current_user.id
    )
    db.add(contact)
    db.commit()
    db.refresh(contact)
    return contact

@contact_router.put("/contacts/{contact_id}", response_model=ContactResponse)
def update_contact(
    contact_in: ContactUpdate,
    contact_id: int = Path(...),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    contact = db.query(Contact).filter(Contact.id == contact_id, Contact.user_id == current_user.id).first()
    if not contact:
        raise HTTPException(status_code=404, detail="Contact not found")

    for field, value in contact_in.dict(exclude_unset=True).items():
        setattr(contact, field, value)

    db.commit()
    db.refresh(contact)
    return contact

@contact_router.delete("/contacts/{contact_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_contact(
    contact_id: int = Path(...),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    contact = db.query(Contact).filter(Contact.id == contact_id, Contact.user_id == current_user.id).first()
    if not contact:
        raise HTTPException(status_code=404, detail="Contact not found")
    db.delete(contact)
    db.commit()
    return None

@contact_router.get("/contacts/{contact_id}/notes", response_model=List[NoteResponse])
def get_contact_notes(
    contact_id: int = Path(...),
    current_user: "User" = Depends(get_current_user),  # type: ignore
    db: Session = Depends(get_db)
):
    contact = db.query(Contact).filter(Contact.id == contact_id, Contact.user_id == current_user.id).first()
    if not contact:
        raise HTTPException(status_code=404, detail="Contact not found")
    return db.query(Note).filter(Note.contact_id == contact_id).all()

@contact_router.post("/contacts/{contact_id}/notes", response_model=NoteResponse, status_code=status.HTTP_201_CREATED)
