import React, { useState, useEffect } from 'react';
import API from '../api';

export default function TaskListPage() {
  const [tasks, setTasks] = useState([]);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const response = await API.get('/tasks');
      if (response.data && Array.isArray(response.data.items)) {
        setTasks(response.data.items);
      } else if (Array.isArray(response.data)) {
        setTasks(response.data);
      }
    } catch (err) {
      setError('Failed to fetch tasks');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;
    try {
      const response = await API.post('/tasks', { title: newTaskTitle, done: false });
      setTasks((prev) => [...prev, response.data]);
      setNewTaskTitle('');
    } catch (err) {
      setError('Failed to add task');
    }
  };

  const handleToggleTask = async (task) => {
    try {
      const updatedDone = !task.done;
      const response = await API.put(`/tasks/${task.id}`, { ...task, done: updatedDone });
      setTasks((prev) => prev.map((t) => (t.id === task.id ? response.data : t)));
    } catch (err) {
      setError('Failed to update task');
    }
  };

  const handleDeleteTask = async (id) => {
    try {
      await API.delete(`/tasks/${id}`);
      setTasks((prev) => prev.filter((t) => t.id !== id));
    } catch (err) {
      setError('Failed to delete task');
    }
  };

  const filteredTasks = tasks.filter((task) =>
    task.title ? task.title.toLowerCase().includes(searchQuery.toLowerCase()) : false
  );

  return (
    <div className="task-list-container">
      <h1>Task List</h1>
      {error && <p className="error-message">{error}</p>}

      <div className="search-bar">
        <label htmlFor="search-input">Search Tasks:</label>
        <input
          id="search-input"
          type="text"
          placeholder="Search tasks..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          aria-label="Search tasks"
        />
      </div>

      <form onSubmit={handleAddTask} className="add-task-form">
        <label htmlFor="new-task-input">New Task:</label>
        <input
          id="new-task-input"
          type="text"
          placeholder="Add a new task..."
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          aria-label="New task title"
        />
        <button type="submit">Add Task</button>
      </form>

      {loading ? (
        <p>Loading tasks...</p>
      ) : (
        <ul className="task-list">
          {filteredTasks.map((task) => (
            <li key={task.id} className={`task-item ${task.done ? 'completed' : ''}`}>
              <label htmlFor={`task-checkbox-${task.id}`} className="sr-only">
                Toggle task completion
              </label>
              <input
                id={`task-checkbox-${task.id}`}
                type="checkbox"
                checked={task.done || false}
                onChange={() => handleToggleTask(task)}
                aria-label={`Mark ${task.title} as ${task.done ? 'incomplete' : 'complete'}`}
              />
              <span className="task-title">{task.title}</span>
              <button onClick={() => handleDeleteTask(task.id)} aria-label={`Delete task ${task.title}`}>
                Delete
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

