from fastapi import APIRouter, Depends, HTTPException, Query, Path, Response
from sqlalchemy.orm import Session
from app.database import get_db
from app.schemas.user import UserCreate, UserUpdate
from app.utils.auth import get_current_user
from app.models.user import User

user_router = APIRouter()

@user_router.get("/users")
def list_users(
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
):
    total = db.query(User).count()
    users = db.query(User).offset(offset).limit(limit).all()
    return {
        "items": [{"id": u.id, "username": u.username} for u in users],
        "total": total,
    }

@user_router.get("/users/{user_id}")
def get_user(
    user_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
):
    user = db.query(User).filter(User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="Not found")
    return {"id": user.id, "username": user.username}

@user_router.post("/users", status_code=201)
def create_user(
    user_in: UserCreate,
    db: Session = Depends(get_db),
):
    # Ensure username uniqueness
    existing = db.query(User).filter(User.username == user_in.username).first()
    if existing:
        raise HTTPException(status_code=400, detail="Username already exists")
    user = User(username=user_in.username, hashed_password=user_in.hashed_password)
    db.add(user)
    db.commit()
    db.refresh(user)
    return {"id": user.id, "username": user.username}

@user_router.put("/users/{user_id}")
def update_user(
    user_in: UserUpdate,
    user_id: int = Path(..., ge=1),
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    # Optionally restrict updates to the authenticated user
    if current_user.id != user_id:
        raise HTTPException(status_code=403, detail="Operation not permitted")
    user = db.query(User).filter(User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="Not found")
    if user_in.username is not None:
        # Check for uniqueness when changing username
        existing = (
            db.query(User)
            .filter(User.username == user_in.username, User.id != user_id)
            .first()
        )
        if existing:
            raise HTTPException(status_code=400, detail="Username already exists")
        user.username = user_in.username
    if getattr(user_in, "hashed_password", None) is not None:
        user.hashed_password = user_in.hashed_password
    db.commit()
    db.refresh(user)
    return {"id": user.id, "username": user.username}

@user_router.delete("/users/{user_id}", status_code=204)
def delete_user(
    user_id: int = Path(..., ge=1),
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    if current_user.id != user_id:
        raise HTTPException(status_code=403, detail="Operation not permitted")
    user = db.query(User).filter(User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="Not found")
    db.delete(user)
    db.commit()
    return Response(status_code=204)

