from fastapi import APIRouter, Depends, HTTPException, Query, Path
from sqlalchemy.orm import Session
from typing import Optional, List, Any

from app.database import get_db
from app.models.course import Course
from app.models.enrollment import Enrollment
from app.models.user import User
from app.schemas.course import CourseCreate, CourseUpdate
from app.utils.auth import get_current_user

from pydantic import BaseModel, ConfigDict

course_router = APIRouter()

class CourseRead(BaseModel):
    id: int
    code: str
    title: str
    credits: int
    capacity: int
    enrolled_count: Optional[int] = None

    model_config = ConfigDict(from_attributes=True)

@course_router.get("/courses")
def list_courses(
    keyword: Optional[str] = Query(None, description="Search by code or title"),
    semester_id: Optional[int] = Query(None, description="Filter by semester"),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
    current_user: Any = Depends(get_current_user),
):
    query = db.query(Course)
    if keyword:
        like_pattern = f"%{keyword}%"
        query = query.filter(
            (Course.code.ilike(like_pattern)) | (Course.title.ilike(like_pattern))
        )
    if semester_id:
        query = query.filter(Course.semester_id == semester_id)
    total = query.count()
    courses: List[Any] = query.offset(offset).limit(limit).all()
    result = [CourseRead.model_validate(c, from_attributes=True) for c in courses]
    return {"items": result, "total": total}

@course_router.get("/courses/{course_id}")
def get_course(
    course_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: Any = Depends(get_current_user),
):
    course = db.query(Course).filter(Course.id == course_id).first()
    if not course:
        raise HTTPException(status_code=404, detail="Not found")
    enrolled_count = db.query(Enrollment).filter(Enrollment.course_id == course_id).count()
    course_data = CourseRead.model_validate(course, from_attributes=True)
    course_data.enrolled_count = enrolled_count
    return course_data

@course_router.post("/courses", status_code=201)
def create_course(
    course_in: CourseCreate,
    db: Session = Depends(get_db),
    current_user: Any = Depends(get_current_user),
):
    allowed_fields = Course.__table__.columns.keys()
    data = {k: v for k, v in course_in.model_dump().items() if k in allowed_fields}
    data["instructor_id"] = current_user.id
    course = Course(**data)
    db.add(course)
    db.commit()
    db.refresh(course)
    return CourseRead.model_validate(course, from_attributes=True)

@course_router.put("/courses/{course_id}")
def update_course(
    course_in: CourseUpdate,
    course_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: Any = Depends(get_current_user),
):
    course = db.query(Course).filter(Course.id == course_id).first()
    if not course:
        raise HTTPException(status_code=404, detail="Not found")
    allowed_fields = Course.__table__.columns.keys()
    update_data = {k: v for k, v in course_in.model_dump(exclude_unset=True).items() if k in allowed_fields}
    for attr, value in update_data.items():
        setattr(course, attr, value)
    db.commit()
    db.refresh(course)
    return CourseRead.model_validate(course, from_attributes=True)

@course_router.delete("/courses/{course_id}")
def delete_course(
    course_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: Any = Depends(get_current_user),
):
    course = db.query(Course).filter(Course.id == course_id).first()
    if not course:
        raise HTTPException(status_code=404, detail="Not found")
    db.delete(course)
    db.commit()
    return {"detail": "Course deleted"}

