from datetime import date
from fastapi import APIRouter, Depends, HTTPException, Query, Path, Response, status
from sqlalchemy.orm import Session
from typing import Optional

from app.database import get_db
from app.models.students import Student
from app.schemas.student import StudentCreate, StudentUpdate, StudentResponse
from app.utils.auth import get_current_user, oauth2_scheme

student_router = APIRouter()

@student_router.get("/students", response_model=dict)
def list_students(
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    name: Optional[str] = Query(None),
    grade: Optional[str] = Query(None),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    query = db.query(Student)
    if name:
        query = query.filter(Student.name.ilike(f"%{name}%"))
    if grade:
        query = query.filter(Student.grade == grade)
    total = query.count()
    students = query.offset(offset).limit(limit).all()
    students = [StudentResponse.model_validate(x, from_attributes=True) for x in students]
    return {"items": students, "total": total}

@student_router.get("/students/{student_id}", response_model=StudentResponse)
def get_student(
    student_id: int = Path(...),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    student = db.query(Student).filter(Student.id == student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Not found")
    return StudentResponse.model_validate(student, from_attributes=True)

@student_router.post("/students", response_model=StudentResponse, status_code=status.HTTP_201_CREATED)
def create_student(
    student_in: StudentCreate,
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    # Exclude primary key and auto-handled fields from input
    data = {k: v for k, v in student_in.model_dump().items() if k in Student.__table__.columns.keys() and k not in {"id", "enrollment_date"}}
    student = Student(**data, enrollment_date=date.today())
    db.add(student)
    db.commit()
    db.refresh(student)
    return StudentResponse.model_validate(student, from_attributes=True)

@student_router.put("/students/{student_id}", response_model=StudentResponse)
def update_student(
    student_in: StudentUpdate,
    student_id: int = Path(...),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    student = db.query(Student).filter(Student.id == student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Not found")
    for field, value in student_in.model_dump(exclude_unset=True).items():
        setattr(student, field, value)
    db.commit()
    db.refresh(student)
    return StudentResponse.model_validate(student, from_attributes=True)

@student_router.delete("/students/{student_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_student(
    student_id: int = Path(...),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    student = db.query(Student).filter(Student.id == student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Not found")
    db.delete(student)
    db.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

