import builtins
from sqlalchemy import Column, Integer, REAL, Date, Text, DateTime, ForeignKey
from app.database import Base
from sqlalchemy.sql import func

class Expense(Base):
    __tablename__ = 'expenses'
    __table_args__ = {"extend_existing": True}

    id = Column(Integer, primary_key=True, nullable=False)
    user_id = Column(Integer, ForeignKey('users.id'), nullable=False)
    category_id = Column(Integer, ForeignKey('categories.id'), nullable=False)
    amount = Column(REAL, nullable=True)
    date = Column(Date, nullable=True)
    notes = Column(Text)
    created_at = Column(DateTime, server_default=func.now(), nullable=False)

    @builtins.property
    def category(self):
        from sqlalchemy import inspect as _sa_inspect
        _sess = _sa_inspect(self).session
        if _sess is None or self.category_id is None:
            return None
        from app.models.categories import Category
        return _sess.query(Category).get(self.category_id)

    @builtins.property
    def user(self):
        from sqlalchemy import inspect as _sa_inspect
        _sess = _sa_inspect(self).session
        if _sess is None or self.user_id is None:
            return None
        from app.models.users import User
        return _sess.query(User).get(self.user_id)

