from fastapi import APIRouter, Depends, HTTPException
from app.models.user import User
from app.schemas.auth import LoginRequest, RegisterRequest, Token
from app.utils.auth import create_access_token, get_password_hash, verify_password, get_current_user
from app.database import get_db
from sqlalchemy.orm import Session

auth_router = APIRouter()

@auth_router.post('/auth/signup')
def signup(user_in: RegisterRequest, db: Session = Depends(get_db)):
    user = User(email=user_in.email, display_name=user_in.display_name)
    user.hashed_password = get_password_hash(user_in.password)
    db.add(user)
    db.commit()
    db.refresh(user)
    return {'id': user.id, 'email': user.email, 'display_name': user.display_name}

@auth_router.post('/auth/login')
def login(login_in: LoginRequest, db: Session = Depends(get_db)):
    user = db.query(User).filter(User.email == login_in.email).first()
    if not user or not verify_password(login_in.password, user.hashed_password):
        raise HTTPException(status_code=400, detail='Invalid credentials')
    access_token = create_access_token(data={'sub': user.email})
    return {'access_token': access_token, 'token_type': 'bearer', 'user_id': user.id, 'email': user.email, 'display_name': user.display_name}

@auth_router.get('/auth/me')
def me(current_user: User = Depends(get_current_user)):
    return {'id': current_user.id, 'email': current_user.email, 'display_name': getattr(current_user, 'display_name', None), 'role': getattr(current_user, 'role', None)}

