from pydantic import BaseModel, Field
from sqlalchemy.orm import Session

from app.database import get_db
from app.utils.auth import (
    get_password_hash,
    verify_password,
    create_access_token,
    get_current_user,
    _get_user_model,
    _login_field,
)
from app.models.user import User

auth_router = APIRouter(prefix="/auth")


class SignupRequest(BaseModel):
    model_config = {"from_attributes": True}
    email: str = Field(min_length=1)
    password: str = Field(min_length=1)
    display_name: str = ""


class LoginRequest(BaseModel):
    model_config = {"from_attributes": True}
    email: str = Field(min_length=1)
    password: str = Field(min_length=1)


def _identifier_value(login_field: str, email: str) -> str:
    return email if login_field == "email" else email.split("@")[0]


def _make_user(email: str, password: str, display_name: str = ""):
    """Create a User instance compatible with any custom user model.

    The function inspects the actual User model to determine which columns
    exist and populates sensible defaults for required non‑nullable fields.
    """
    UserModel = _get_user_model()
    cols = {c.name for c in UserModel.__table__.columns}
    login_field = _login_field(UserModel)
    identifier = _identifier_value(login_field, email)
    kw: dict = {login_field: identifier}
    if login_field != "email" and "email" in cols:
        kw["email"] = email
    pwd_hash = get_password_hash(password)
    for field in ("hashed_password", "password_hash", "password"):
        if field in cols:
            kw[field] = pwd_hash
            break
    if "display_name" in cols:
        kw["display_name"] = display_name or email.split("@")[0]
    if "username" in cols and "username" not in kw:
        kw["username"] = email.split("@")[0]
    if "is_active" in cols:
        kw["is_active"] = True
    if "role" in cols:
        kw["role"] = "user"
    # Fill any remaining NOT NULL columns that have no default so injected auth
    # routes work even when the LLM adds custom non‑nullable columns (e.g. status).
    _COL_STR_DEFAULTS = {
        "status": "active",
        "state": "active",
        "type": "user",
        "gender": "other",
        "plan": "free",
        "tier": "basic",
        "account_type": "standard",
        "subscription": "free",
    }
    for col in UserModel.__table__.columns:
        if col.name in kw or col.primary_key:
            continue
        if col.nullable or col.default is not None or col.server_default is not None:
            continue
        col_type = type(col.type).__name__.lower()
        if col.name in _COL_STR_DEFAULTS:
            kw[col.name] = _COL_STR_DEFAULTS[col.name]
        elif any(t in col_type for t in ("str", "text", "char", "varchar")):
            kw[col.name] = "active"
        elif any(t in col_type for t in ("int", "float", "numeric", "decimal")):
            kw[col.name] = 0
        elif "bool" in col_type:
            kw[col.name] = True
        else:
            kw[col.name] = ""
    return UserModel(**{k: v for k, v in kw.items() if k in cols})


def _read_password(user: User) -> str | None:
    """Extract the stored password hash from a user instance.

    The function checks common column names used for password storage and
    returns the value if present.
    """
    for field in ("hashed_password", "password_hash", "password"):
        if hasattr(user, field):
            return getattr(user, field)
    return None


@auth_router.post("/signup", response_model=User)
def signup(request: SignupRequest, db: Session = Depends(get_db)):
    UserModel = _get_user_model()
    login_field = _login_field(UserModel)
    identifier = _identifier_value(login_field, request.email)
    existing = (
        db.query(UserModel)
        .filter(getattr(UserModel, login_field) == identifier)
        .first()
    )
    if existing:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="User already exists",
        )
    user = _make_user(request.email, request.password, request.display_name)
    db.add(user)
    db.commit()
    db.refresh(user)
    return user


@auth_router.post("/login")
def login(request: LoginRequest, db: Session = Depends(get_db)):
    UserModel = _get_user_model()
    login_field = _login_field(UserModel)
    identifier = _identifier_value(login_field, request.email)
    user = (
        db.query(UserModel)
        .filter(getattr(UserModel, login_field) == identifier)
        .first()
    )
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid credentials",
        )
    stored_hash = _read_password(user)
    if not stored_hash or not verify_password(request.password, stored_hash):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid credentials",
        )
    access_token = create_access_token(data={"sub": str(user.id)})
    return {"access_token": access_token}


@auth_router.get("/me", response_model=User)
def read_current_user(current_user: User = Depends(get_current_user)):
    return current_user

