from sqlalchemy import Column, Integer, String, Date, func
from app.database import Base

class User(Base):
    __tablename__ = 'users'
    __table_args__ = {"extend_existing": True}

    id = Column(Integer, primary_key=True, nullable=False)
    email = Column(String, nullable=False)
    display_name = Column(String, nullable=True)
    created_at = Column(Date, server_default=func.now(), nullable=False)
    updated_at = Column(Date, server_default=func.now(), onupdate=func.now(), nullable=False)

    @property
    def cases(self):
        from sqlalchemy import inspect as _sa_inspect
        _sess = _sa_inspect(self).session
        if _sess is None:
            return []
        from app.models.case import Case
        return _sess.query(Case).filter(Case.user_id == self.id).all()

