from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from app.database import get_db
from app.utils.auth import get_current_user
from app.models.reviews import Review
from app.schemas.review import ReviewCreate, ReviewUpdate, ReviewResponse

review_router = APIRouter()

@review_router.get('/reviews')
def get_reviews(
    search: str = Query(None),
    class_id: int = Query(None),
    student_id: int = Query(None),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db)
):
    query = db.query(Review)
    if search:
        query = query.filter(Review.comment.ilike(f'%{search}%'))
    if class_id:
        query = query.filter(Review.class_id == class_id)
    if student_id:
        query = query.filter(Review.student_id == student_id)
    total = query.count()
    items = query.offset(offset).limit(limit).all()
    return {'items': items, 'total': total}

@review_router.get('/reviews/{id}')
def get_review(id: int, db: Session = Depends(get_db)):
    review = db.query(Review).filter(Review.id == id).first()
    if not review:
        raise HTTPException(status_code=404, detail='Not found')
    return review

@review_router.post('/reviews', response_model=ReviewResponse, status_code=201)
def create_review(
    review_in: ReviewCreate,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    # Ensure the review is linked to the authenticated student
    review_data = review_in.dict()
    review_data['student_id'] = current_user['id']
    review = Review(**{k: v for k, v in review_data.items() if k in Review.__table__.columns.keys()})
    db.add(review)
    db.commit()
    db.refresh(review)
    return review

@review_router.put('/reviews/{id}', response_model=ReviewResponse)
def update_review(
    id: int,
    review_in: ReviewUpdate,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    review = db.query(Review).filter(Review.id == id).first()
    if not review:
        raise HTTPException(status_code=404, detail='Not found')
    # Optional: ensure only the owner can modify
    if review.student_id != current_user['id']:
        raise HTTPException(status_code=403, detail='Forbidden')
    for key, value in review_in.dict(exclude_unset=True).items():
        setattr(review, key, value)
    db.commit()
    db.refresh(review)
    return review

@review_router.delete('/reviews/{id}', status_code=204)
def delete_review(
    id: int,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    review = db.query(Review).filter(Review.id == id).first()
    if not review:
        raise HTTPException(status_code=404, detail='Not found')
    if review.student_id != current_user['id']:
        raise HTTPException(status_code=403, detail='Forbidden')
    db.delete(review)
    db.commit()

