from sqlalchemy import Column, Integer, Text, Date, func
from app.database import Base

class Item(Base):
    __tablename__ = 'items'
    __table_args__ = {"extend_existing": True}

    id = Column(Integer, primary_key=True, autoincrement=True, nullable=False)
    name = Column(Text, nullable=False)
    description = Column(Text, nullable=True)
    created_at = Column(Date, server_default=func.now(), nullable=False)

    @property
    def orders(self):
        from sqlalchemy import inspect as _sa_inspect
        _sess = _sa_inspect(self).session
        if _sess is None:
            return []
        from app.models.orders import Order
        return _sess.query(Order).filter(Order.item_id == self.id).all()

    @property
    def reviews(self):
        from sqlalchemy import inspect as _sa_inspect
        _sess = _sa_inspect(self).session
        if _sess is None:
            return []
        from app.models.reviews import Review
        return _sess.query(Review).filter(Review.item_id == self.id).all()

