    VaccinationRecordCreate,
    VaccinationRecordUpdate,
)
from app.models.vaccination_records import VaccinationRecord
from app.utils.auth import get_current_user
from app.models.user import User

vaccination_record_router = APIRouter()

# Helper to serialize a VaccinationRecord ORM object

def _serialize(record) -> dict:
    return {
        "id": record.id,
        "vaccine": record.vaccine,
        "date_given": record.date_given.isoformat() if record.date_given else None,
    }

@vaccination_record_router.get("/vaccination_records")
def list_vaccination_records(
    search: Optional[str] = Query(None, min_length=1),
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    db: Session = Depends(get_db),
):
    query = db.query(VaccinationRecord)
    if search:
        query = query.filter(VaccinationRecord.vaccine.ilike(f"%{search}%"))
    total = query.count()
    records = query.offset(offset).limit(limit).all()
    return {"items": [_serialize(r) for r in records], "total": total}

@vaccination_record_router.get("/vaccination_records/{record_id}")
def get_vaccination_record(
    record_id: int,
    db: Session = Depends(get_db),
):
    record = db.query(VaccinationRecord).filter(VaccinationRecord.id == record_id).first()
    if not record:
        raise HTTPException(status_code=404, detail="Not found")
    return _serialize(record)

@vaccination_record_router.post("/vaccination_records", status_code=201)
def create_vaccination_record(
    payload: VaccinationRecordCreate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    new_record = VaccinationRecord(
        vaccine=payload.vaccine,
        date_given=payload.date_given,
        patient_id=current_user.id,
    )
    db.add(new_record)
    db.commit()
    db.refresh(new_record)
    return _serialize(new_record)

@vaccination_record_router.put("/vaccination_records/{record_id}")
def update_vaccination_record(
    payload: VaccinationRecordUpdate,
    record_id: int,
    db: Session = Depends(get_db),
):
    record = db.query(VaccinationRecord).filter(VaccinationRecord.id == record_id).first()
    if not record:
        raise HTTPException(status_code=404, detail="Not found")
    record.vaccine = payload.vaccine
    if payload.date_given is not None:
        record.date_given = payload.date_given
    db.commit()
    db.refresh(record)
    return _serialize(record)

@vaccination_record_router.delete("/vaccination_records/{record_id}", status_code=204)
def delete_vaccination_record(
    record_id: int,
    db: Session = Depends(get_db),
):
    record = db.query(VaccinationRecord).filter(VaccinationRecord.id == record_id).first()
    if not record:
        raise HTTPException(status_code=404, detail="Not found")
    db.delete(record)
    db.commit()

