from app.models.medications import Medication
from app.schemas.medication import MedicationCreate
from app.schemas.medication import MedicationUpdate
from app.schemas.medication import MedicationResponse
from app.utils.auth import get_current_user
from app.models.user import User

medication_router = APIRouter()

@medication_router.get("/medications")
def get_medications(limit: int = Query(50, ge=1, le=500), offset: int = Query(0, ge=0), db: Session = Depends(get_db)):
    medications = db.query(Medication).offset(offset).limit(limit).all()
    total = db.query(Medication).count()
    return {"items": medications, "total": total}

@medication_router.get("/medications/search")
def search_medications(search: str = Query(None), db: Session = Depends(get_db)):
    try:
        query = db.query(Medication)
        if search:
            query = query.filter(Medication.name.ilike(f"%{search}%"))
        medications = query.all()
        return medications
    except Exception:
        return {}

@medication_router.get("/medications/{id}")
def get_medication(id: int, db: Session = Depends(get_db)):
    medication = db.query(Medication).filter(Medication.medication_id == id).first()
    if not medication:
        raise HTTPException(status_code=404, detail="Not found")
    return medication

@medication_router.post("/medications", status_code=201)
def create_medication(medication_in: MedicationCreate, db: Session = Depends(get_db), current_user: User = Depends(get_current_user)):
