def update_medication(id: int, medication_in: MedicationUpdate, db: Session = Depends(get_db)):
    medication = db.query(Medication).filter(Medication.medication_id == id).first()
    if not medication:
        raise HTTPException(status_code=404, detail="Not found")
    for key, value in medication_in.dict(exclude_unset=True).items():
