import React, { useEffect, useState } from 'react';
import API from '../api';
import { toast } from 'react-toastify';

const MyRegistrationsPage = () => {
  const [registrations, setRegistrations] = useState([]);
  const [toast, setToast] = useState(null);
  const [toastColorClass, setToastColorClass] = useState('bg-green-500');

  useEffect(() => {
    const fetchRegistrations = async () => {
      try {
        const response = await API.get('/registrations');
        setRegistrations(response.data.items);
      } catch (error) {
        setToast({ msg: 'Failed to fetch registrations' });
        setToastColorClass('bg-red-500');
      }
    };
    fetchRegistrations();
  }, []);

  return (
    <div>
      <h1>My Registrations</h1>
      <ul>
        {registrations.map((registration) => (
          <li key={registration.id}>{registration.eventName}</li>
        ))}
      </ul>
      {toast && (
        <div className={`animate-scale-in fixed bottom-4 right-4 px-4 py-3 rounded-xl shadow-lg text-sm font-medium text-white z-50 ${toastColorClass}`}> 
          {toast.msg}
        </div>
      )}
    </div>
  );
};

export default MyRegistrationsPage;
